{"source": "def investigate(context, acquire):
    history = acquire("history")
    actions = context.get("actions", [])
    goal = context.get("goal")

    def simulate(put_mode, channel_mode, trigger):
        # put_mode: 'ignore', 'replace', 'upsert'
        # channel_mode: 'changes', 'total_main', 'total_both'
        # trigger: bool
        main = {}
        other = {}
        committed = {}
        main_changes = 0
        main_total = 0
        other_total = 0
        in_tx = None
        tx_snapshot = None
        tx_changes = 0
        tx_total = 0
        tx_other_total = 0
        tx_trigger = 0
        last_changes = 0
        last_total = 0
        last_other_total = 0
        last_trigger = 0

        def do_put(conn, key, value):
            nonlocal main_changes, main_total, other_total, last_changes, last_total, last_other_total, last_trigger
            if conn == 'main':
                d = main
            else:
                d = other
            changed = 0
            trig = 0
            if put_mode == 'ignore':
                if key not in d:
                    d[key] = value
                    changed = 1
            elif put_mode == 'replace':
                if key in d:
                    if d[key] != value:
                        d[key] = value
                        changed = 1
                    else:
                        changed = 0
                else:
                    d[key] = value
                    changed = 1
            else:
                if key in d:
                    if d[key] != value:
                        d[key] = value
                        changed = 1
                    else:
                        changed = 0
                else:
                    d[key] = value
                    changed = 1
            if changed and trigger:
                trig = 1
            if conn == 'main':
                main_changes = changed
                main_total += changed
                last_changes = changed
                last_total = main_total
                last_other_total = other_total
                last_trigger = trig
            else:
                other_total += changed
                last_changes = 0
                last_total = main_total
                last_other_total = other_total
                last_trigger = trig
            return changed, trig

        def do_delete(conn, key):
            nonlocal main_changes, main_total, other_total, last_changes, last_total, last_other_total, last_trigger
            if conn == 'main':
                d = main
            else:
                d = other
            changed = 0
            trig = 0
            if key in d:
                del d[key]
                changed = 1
            if changed and trigger:
                trig = 1
            if conn == 'main':
                main_changes = changed
                main_total += changed
                last_changes = changed
                last_total = main_total
                last_other_total = other_total
                last_trigger = trig
            else:
                other_total += changed
                last_changes = 0
                last_total = main_total
                last_other_total = other_total
                last_trigger = trig
            return changed, trig

        def do_update(conn, key, value):
            nonlocal main_changes, main_total, other_total, last_changes, last_total, last_other_total, last_trigger
            if conn == 'main':
                d = main
            else:
                d = other
            changed = 0
            trig = 0
            if key in d:
                if d[key] != value:
                    d[key] = value
                    changed = 1
            if changed and trigger:
                trig = 1
            if conn == 'main':
                main_changes = changed
                main_total += changed
                last_changes = changed
                last_total = main_total
                last_other_total = other_total
                last_trigger = trig
            else:
                other_total += changed
                last_changes = 0
                last_total = main_total
                last_other_total = other_total
                last_trigger = trig
            return changed, trig

        for act in actions:
            op = act.get('op')
            conn = act.get('connection', 'main')
            if op == 'begin':
                in_tx = conn
                tx_snapshot = dict(main) if conn == 'main' else dict(other)
                tx_changes = main_changes
                tx_total = main_total
                tx_other_total = other_total
                tx_trigger = last_trigger
            elif op == 'commit':
                if in_tx == 'main':
                    committed = dict(main)
                else:
                    committed = dict(other)
                in_tx = None
            elif op == 'rollback':
                if in_tx == 'main':
                    main = dict(tx_snapshot)
                    main_changes = tx_changes
                    main_total = tx_total
                    other_total = tx_other_total
                else:
                    other = dict(tx_snapshot)
                    main_changes = tx_changes
                    main_total = tx_total
                    other_total = tx_other_total
                in_tx = None
            elif op == 'put':
                do_put(conn, act.get('key'), act.get('value'))
            elif op == 'update':
                do_update(conn, act.get('key'), act.get('value'))
            elif op == 'delete':
                do_delete(conn, act.get('key'))

        if in_tx is None:
            committed = dict(main)
        else:
            if in_tx == 'main':
                committed = dict(tx_snapshot)
            else:
                committed = dict(tx_snapshot)

        if channel_mode == 'changes':
            ch = last_changes
        elif channel_mode == 'total_main':
            ch = last_total
        else:
            ch = last_total + last_other_total
        return ch, len(committed), sum(committed.values())

    put_modes = ['ignore', 'replace', 'upsert']
    channel_modes = ['changes', 'total_main', 'total_both']
    triggers = [False, True]

    candidates = []
    for pm in put_modes:
        for cm in channel_modes:
            for tr in triggers:
                ok = True
                for rec in history:
                    acts = rec.get('actions', [])
                    obs = rec.get('observed', {})
                    ch, cc, cs = simulate(pm, cm, tr)
                    if ch != obs.get('channel') or cc != obs.get('committed_count') or cs != obs.get('committed_sum'):
                        ok = False
                        break
                if ok:
                    candidates.append((pm, cm, tr))

    if not candidates:
        return {'value': None, 'unresolved': True}

    results = set()
    for pm, cm, tr in candidates:
        ch, cc, cs = simulate(pm, cm, tr)
        if goal == 'channel':
            results.add(ch)
        elif goal == 'committed_count':
            results.add(cc)
        elif goal == 'committed_sum':
            results.add(cs)
        else:
            return {'value': None, 'unresolved': True}

    if len(results) == 1:
        return {'value': results.pop(), 'unresolved': False}
    return {'value': None, 'unresolved': True}
", "scope": "Predicts channel, committed_count, or committed_sum for a fresh action sequence by enumerating the disclosed 18-member family (3 put modes x 3 channel modes x 2 trigger states) and keeping only members consistent with all calibration receipts.", "lesson": "The champion returned unresolved for everything. The revised program simulates each family member over the calibration history, filters by exact match on channel, committed_count, and committed_sum, then predicts the goal only when all surviving members agree. This preserves uncertainty when evidence cannot distinguish members."}
